/**
 * The parts of the `flarum` global Community Reviews reads at runtime: which extensions are enabled, and modules
 * of optional extensions (never a build-time import, so the bundle is the same whether they exist or not).
 */

export const runtime = () => globalThis.flarum;
export const has = extension => extension in (runtime()?.extensions ?? {});

/** A module's default export, from a lazily loaded core module or another extension's module. */
export function defaultExport(mod) {
  const record = mod;
  return record?.default ?? mod;
}
flarum.reg.add('ernestdefoe-community-reviews', 'common/runtime', { runtime: runtime,has: has,defaultExport: defaultExport, });